/**
 * Ba Dan's top-down scene (ADR 0104, phase T3): the baked plate and the upright atlas
 * (`baDan.topdown.art.ts`, generated by `scripts/art/topdown/pack-ground.ts`) laid out by the placed
 * objects (`baDan.topdown.ts`). Every static shadow, contact and apron is in the plate, so no piece
 * asks the renderer for a runtime shadow, and the canal is painted (`paintedWater`).
 */
import type { MapScene, SceneScenery } from '../../core/types';
import {
  BA_DAN_TOPDOWN_CHIMNEYS,
  BA_DAN_TOPDOWN_EXTENT,
  BA_DAN_TOPDOWN_GROUND,
  BA_DAN_TOPDOWN_UPRIGHT_ATLAS,
  BA_DAN_TOPDOWN_UPRIGHTS,
} from './baDan.topdown.art';
import { BA_DAN_TOPDOWN_OBJECTS } from './baDan.topdown';

/** The standing pieces, each sorted by its base and faded when it hides a figure. */
const SCENERY: readonly SceneScenery[] = BA_DAN_TOPDOWN_OBJECTS.flatMap((o) => {
  const art = BA_DAN_TOPDOWN_UPRIGHTS[o.id];
  if (!art) return [];
  return [
    {
      id: `badan.td.${o.id}`,
      url: BA_DAN_TOPDOWN_UPRIGHT_ATLAS.url,
      sourceRect: art.sourceRect,
      x: art.x,
      y: art.y,
      width: art.width,
      height: art.height,
      footprint: o.footprint,
      depth: o.depth,
      ...(o.exterior && { exterior: true }),
      ...(o.fadeWhenOccluding && { fadeWhenOccluding: true }),
      ...(o.revealOccluded && { revealOccluded: true }),
      contactShadow: false,
      castShadow: false,
    } satisfies SceneScenery,
  ];
});

export const BA_DAN_TOPDOWN_SCENE: MapScene = {
  paintedWater: true,
  paintExtent: BA_DAN_TOPDOWN_EXTENT,
  chimneys: BA_DAN_TOPDOWN_CHIMNEYS,
  // The trees' trunks, where their leaves drift from.
  canopies: BA_DAN_TOPDOWN_OBJECTS.filter((o) => o.kind === 'tree' && o.sprite !== 'bush').map(
    (o) => ({ x: o.depth.x, y: o.depth.y - 1 }),
  ),
  ground: BA_DAN_TOPDOWN_GROUND,
  scenery: SCENERY,
};
